function stepText(doc: DocumentInfo): string {
    switch (doc.status) {
        case "pending":
            return "Queued for processing…";
        case "processing":
            return "Parsing & indexing…";
        case "completed":
            return "Ready — indexed for search";
        case "failed":
            return doc.error_msg ? `Failed: ${doc.error_msg}` : "Processing failed";
        default:
            return "";
    }
}

