        const m = msg as Record<string, unknown>;
        // UIMessage format: has a `parts` array
        if (Array.isArray(m.parts)) return m as unknown as UIMessage;
        // Legacy BuddhiAIMessage format: has a `content` field
        if ("content" in m) return legacyMessageToUIMessage(m as unknown as BuddhiAIMessage, index);
        // Unknown shape — emit a warning and return a blank assistant message
        console.warn("[normalizeMessages] Unrecognised message shape at index", index, m);
        return {
            id: `unknown-${index}`,
            role: "assistant" as UIMessage["role"],
            parts: [{ type: "text", text: "" }],
        };
    });
}

async function loadChat(
    chatId: string
): Promise<BuddhiAISavedChat | null> {
    try {
        const idb = await getDB();
        const chat = await getItemByKey<BuddhiAISavedChat>(
            idb,
            "chats",
            chatId
        );
        if (!chat) return null;
        // Normalise messages to UIMessage[] — handles legacy BuddhiAIMessage format
        return { ...chat, messages: normalizeMessages(chat.messages as unknown[]) };
    } catch (error) {
        console.error("[loadChat] error:", error);
        return null;
    }
}

async function serializeMessagesForStorage(
    messages: UIMessage[]
): Promise<UIMessage[]> {
    return Promise.all(
        messages.map(async (msg) => ({
            ...msg,
            parts: await Promise.all(
                msg.parts.map(async (part) => {
                    if (part.type !== "file") return part;

                    const filePart = part as { type: "file"; url?: string } & Record<string, unknown>;
                    // Already a data URL or no URL at all — nothing to do.
                    if (!filePart.url?.startsWith("blob:")) return part;

                    const dataUrl = await blobUrlToDataUrl(filePart.url);
                    if (!dataUrl) {
                        console.warn(
                            "[serializeMessagesForStorage] Could not serialise blob URL for " +
                            `"${(filePart as { filename?: string }).filename ?? "file"}". ` +
                            "The attachment will not be visible after page reload."
                        );
                        return part; // keep original — better than dropping the part entirely
                    }
                    return { ...part, url: dataUrl };
                })
            ),
        }))
    );
}

function toChatInfo(chat: BuddhiAISavedChat): ChatInfo {
    const numericId = parseInt(chat.id, 10);
    return {
        id: chat.id,
        title: chat.title ?? `Chat ${chat.id}`,
        message_count: chat.messages.length,
        updated_at:
            chat.updated_at ??
            (isNaN(numericId)
                ? new Date().toISOString()
                : new Date(numericId).toISOString()),
    };
}

async function updateExistingChat(
    chatId: string,
    messages: UIMessage[],
    title?: string
): Promise<void> {
    try {
        const idb = await getDB();
        let resolvedTitle = title;
        if (!resolvedTitle) {
            try {
                const existing = await getItemByKey<BuddhiAISavedChat>(
                    idb,
                    "chats",
                    chatId
                );
                resolvedTitle = existing?.title;
            } catch {
                // Non-fatal — title will just be undefined
            }
        }
        const chatData: BuddhiAISavedChat = {
            id: chatId,
            title: resolvedTitle,
            messages,
            updated_at: new Date().toISOString(),
        };
        await updateItemInStore<BuddhiAISavedChat>(
            idb,
            "chats",
            chatData,
            chatId
        );
    } catch (error) {
        console.error("[updateExistingChat] error:", error);
        throw error;
    }
}

async function decomposeConceptIfPossible(
    docId: number,
    root: OkfConcept,
    text: string,
    existingIds: Set<string>
): Promise<OkfConcept[]> {
    const { liteRTModelInstance, liteRTModelStatus } = useLiteRTModelStore.getState();
    if (liteRTModelStatus !== "ready" || !liteRTModelInstance) return [];

    let decomposed: DecomposedConcept[] | null = null;
    try {
        decomposed = await extractConceptsWithLlm(liteRTModelInstance, root.fileName, text);
    } catch (err) {
        console.warn(`[documents] LLM decomposition failed for doc ${docId}, keeping single concept:`, err);
    }
    if (!decomposed) {
        // extractConceptsWithLlm returns null when model runs but produces invalid output;
        // see console for [okf/decompose] warnings about why
        return [];
    }
    if (decomposed.length === 0) return [];

    const slugToId = new Map<string, string>();
    for (const d of decomposed) {
        const id = uniqueConceptId(`${root.id}--${d.slug}`, existingIds);
        existingIds.add(id);
        slugToId.set(d.slug, id);
    }

    const now = new Date().toISOString();
    const subConcepts: OkfConcept[] = decomposed.map((d) => {
        const id = slugToId.get(d.slug)!;
        const relatedLinks = d.relatesTo
            .map((slug) => slugToId.get(slug))
            .filter((relId): relId is string => Boolean(relId) && relId !== id);

        let body = d.body.trim();
        body += `\n\nPart of [${root.frontmatter.title ?? root.id}](/${root.id}.md).`;
        if (relatedLinks.length > 0) {
            body += `\n\nSee also: ${relatedLinks.map((relId) => `[${relId}](/${relId}.md)`).join(", ")}.`;
        }

        const frontmatter: OkfFrontmatter = {
            type: d.type,
            title: d.title,
            ...(d.description ? { description: d.description } : {}),
            ...(d.tags.length > 0 ? { tags: d.tags } : {}),
            generated: { by: PRODUCER_ACTOR, at: now },
        };

        return {
            id,
            frontmatter,
            body,
            raw: serializeFrontmatter(frontmatter, body),
            fileName: root.fileName,
            fileSize: body.length,
            createdAt: now,
        };
    });

    root.body = `${root.body.trim()}\n\n# Concepts\n\n${subConcepts
        .map((c) => `- [${c.frontmatter.title ?? c.id}](/${c.id}.md)`)
        .join("\n")}\n`;
    root.raw = serializeFrontmatter(root.frontmatter, root.body);

    return subConcepts;
}

async function enrichConceptIfPossible(docId: number, concept: OkfConcept): Promise<void> {
    const { liteRTModelInstance, liteRTModelStatus } = useLiteRTModelStore.getState();
    if (liteRTModelStatus !== "ready" || !liteRTModelInstance) return;

    try {
        const fields = await extractFrontmatterWithLlm(liteRTModelInstance, concept.fileName, concept.body);
        if (fields) {
            Object.assign(concept.frontmatter, fields);
            concept.raw = serializeFrontmatter(concept.frontmatter, concept.body);
        }
    } catch (err) {
        console.warn(`[documents] LLM enrichment failed for doc ${docId}, keeping default frontmatter:`, err);
    }
}

function openDocStoreDB(): Promise<IDBDatabase> {
    if (_db) return Promise.resolve(_db);

    return new Promise((resolve, reject) => {
        const req = indexedDB.open(DOC_STORE_DB_NAME, DOC_STORE_DB_VERSION);

        req.onerror = () =>
            reject(new Error(`Failed to open doc store: ${req.error?.message ?? req.error}`));

        req.onsuccess = () => {
            _db = req.result;
            // Re-open on connection close (e.g. version upgrade from another tab)
            req.result.onclose = () => { _db = null; };
            resolve(req.result);
        };

        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(DOC_STORE_NAME)) {
                const store = db.createObjectStore(DOC_STORE_NAME, { keyPath: "id" });
                store.createIndex("status", "status", { unique: false });
            }
        };
    });
}

async function idbDelete(id: number): Promise<void> {
    const db = await openDocStoreDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(DOC_STORE_NAME, "readwrite");
        const req = tx.objectStore(DOC_STORE_NAME).delete(id);
        req.onsuccess = () => resolve();
        req.onerror = () =>
            reject(new Error(`IDB delete failed: ${req.error?.message ?? req.error}`));
    });
}

async function idbGet(id: number): Promise<DocStoreRecord | null> {
    const db = await openDocStoreDB();
