}

async function idbPut(record: DocStoreRecord): Promise<void> {
    const db = await openDocStoreDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(DOC_STORE_NAME, "readwrite");
        const req = tx.objectStore(DOC_STORE_NAME).put(record);
        req.onsuccess = () => resolve();
        req.onerror = () =>
            reject(new Error(`IDB put failed: ${req.error?.message ?? req.error}`));
    });
}

async function idbUpdate(id: number, patch: Partial<DocStoreRecord>): Promise<void> {
    const db = await openDocStoreDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(DOC_STORE_NAME, "readwrite");
        const store = tx.objectStore(DOC_STORE_NAME);
        const getReq = store.get(id);

        getReq.onsuccess = () => {
            const existing: DocStoreRecord | undefined = getReq.result;
            if (!existing) {
                // Doc may have been deleted — silently skip
                resolve();
                return;
            }
            const putReq = store.put({ ...existing, ...patch });
            putReq.onsuccess = () => resolve();
            putReq.onerror = () =>
                reject(new Error(`IDB update failed: ${putReq.error?.message ?? putReq.error}`));
        };

        getReq.onerror = () =>
            reject(new Error(`IDB get failed: ${getReq.error?.message ?? getReq.error}`));
    });
}

async function runPipeline(doc: DocumentInfo, fileData: ArrayBuffer): Promise<void> {
    const store = useDocumentStore.getState();

    try {
        // ── Stage 1: text extraction ──────────────────────────────────────────
        store.updateProgress(doc.id, "reading" as DocPhase, 5);
        await idbUpdate(doc.id, { status: "processing" });

        const file = new File([fileData], doc.original_name);
        const text = await extractText(file);

        // ── Stage 2: build OKF concept ─────────────────────────────────────────
        store.updateProgress(doc.id, "parsing" as DocPhase, 30);
        const existingIds = new Set((await getAllConcepts()).map((c) => c.id));
        const { concept, enrichable } = fileToConcept(file, text, existingIds);
        existingIds.add(concept.id);

        // ── Stage 2b: optional on-device LLM classification ────────────────────
        if (enrichable) {
            store.updateProgress(doc.id, "enriching" as DocPhase, 45);
            await enrichConceptIfPossible(doc.id, concept);
        }

        // ── Stage 2c: optional on-device decomposition into linked sub-concepts ─
        let subConcepts: OkfConcept[] = [];
        if (enrichable) {
            store.updateProgress(doc.id, "enriching" as DocPhase, 60);
            subConcepts = await decomposeConceptIfPossible(doc.id, concept, text, existingIds);
        }
        const allConcepts = [concept, ...subConcepts];

        // ── Stage 3: keyword-index every concept ─────────────────────────────────
        store.updateProgress(doc.id, "indexing" as DocPhase, 70);
        for (const c of allConcepts) {
            await indexConcept(c);
        }

        // ── Stage 4: persist every concept ────────────────────────────────────────
        store.updateProgress(doc.id, "saving" as DocPhase, 90);
        for (const c of allConcepts) {
            await putConcept(c);
        }

        // ── Done ─────────────────────────────────────────────────────────────
        await idbUpdate(doc.id, {
            status: "completed",
            concept_id: concept.id,
            concept_ids: allConcepts.map((c) => c.id),
            error_msg: null,
        });
        store.completeDoc(doc.id);
    } catch (error) {
        const msg =
            error instanceof Error ? error.message : "An unknown error occurred during processing.";
        console.error(`[documents] Pipeline error for doc ${doc.id} ("${doc.original_name}"):`, error);

        // Persist failure state
        try {
            await idbUpdate(doc.id, { status: "failed", error_msg: msg });
        } catch (updateErr) {
            console.error("[documents] Could not persist failure to IDB:", updateErr);
        }

        store.failDoc(doc.id, msg);
    }
}

function toInfo(record: DocStoreRecord): DocumentInfo {
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    const { file_data, ...info } = record;
    return info;
}

async function reconcileInterruptedDocuments(): Promise<void> {
    try {
        const records = await idbGetAll();
        const interrupted = records.filter(
            (r) => r.status === "pending" || r.status === "processing"
        );

        if (interrupted.length === 0) return;

        console.info(
            `[documents] Reconciling ${interrupted.length} interrupted document(s)…`
        );

        const store = useDocumentStore.getState();

        for (const record of interrupted) {
            if (store.activeCount < 5) {
                store.initDoc(record.id);
                runPipeline(toInfo(record), record.file_data);
            } else {
                // Queue is full — mark as failed so the user can re-upload
                await idbUpdate(record.id, {
                    status: "failed",
                    error_msg:
                        "Processing was interrupted (page was closed or refreshed). Please re-upload the file.",
                });
            }
        }
    } catch (err) {
        console.error("[documents] reconcileInterruptedDocuments failed:", err);
    }
}

function clearMemoryContext(chatId: string): void {
    if (!chatId) return;
    try {
        sessionStorage.removeItem(memoryKey(chatId));
    } catch (err) {
        console.warn(`[Memory] Failed to clear sessionStorage for chat "${chatId}":`, err);
    }
}

async function countTokensForMessages(
    instance: LlmInference,
    messages: BuddhiAIMessage[],
    templateVersion: GemmaTemplateVersion,
): Promise<number> {
    if (messages.length === 0) return 0;
    try {
        const prompt = await generateChatTemplate(messages, { templateVersion });
        const count = instance.sizeInTokens(prompt);
        if (count === undefined) {
            console.warn(
                "[Memory] sizeInTokens returned undefined — " +
                "cannot determine token count. Returning 0."
            );
            return 0;
        }
        return count;
    } catch (err) {
        console.warn("[Memory] Failed to count tokens:", err);
        return 0;
    }
}

function extractBuddhiMessages(
    uiMessages: UIMessage[],
    systemPrompt: string,
    templateVersion: GemmaTemplateVersion,
): BuddhiAIMessage[] {
    const converted: BuddhiAIMessage[] = uiMessages.map((msg) => {
        const text = msg.parts
            .filter((p) => p.type === "text")
            .map((p) => (p as { type: "text"; text: string }).text)
            .join("\n");

        return {
            role: msg.role as BuddhiAIMessage["role"],
            content: text,
        };
    });

    if (templateVersion === "gemma4") {
        return [{ role: "system", content: systemPrompt }, ...converted];
    }

    // Gemma 3n: inject system prompt into first user turn.
    if (converted.length > 0 && converted[0].role === "user") {
        return [
            {
                ...converted[0],
                content: `${systemPrompt}\n\n${converted[0].content}`,
            },
            ...converted.slice(1),
        ];
    }

    return converted;
}

function formatMessageForSummary(msg: BuddhiAIMessage): string {
    const role =
        msg.role === "assistant"
            ? "ASSISTANT"
            : msg.role === "user"
                ? "USER"
                : "SYSTEM";

    let text = "";
    if (typeof msg.content === "string") {
        text = msg.content;
    } else {
        text = msg.content
            .filter((p) => p.type === "text")
            .map((p) => p.text ?? "")
            .join(" ");
    }

    // Include tool calls/responses in the text if present (informational).
    if (msg.toolCalls && msg.toolCalls.length > 0) {
        const tools = msg.toolCalls
            .map((tc) => `[tool call: ${tc.name}(${JSON.stringify(tc.arguments)})]`)
            .join(", ");
        text += text ? `\n${tools}` : tools;
    }

    return `${role}: ${text.trim()}`;
}

function getMemoryContext(chatId: string): MemoryContext | null {
    if (!chatId) return null;
    try {
        const raw = sessionStorage.getItem(memoryKey(chatId));
        if (!raw) return null;
        return JSON.parse(raw) as MemoryContext;
    } catch (err) {
        console.warn(`[Memory] Failed to read sessionStorage for chat "${chatId}":`, err);
        return null;
    }
}

function hasMemoryContext(chatId: string): boolean {
    if (!chatId) return false;
    try {
        return sessionStorage.getItem(memoryKey(chatId)) !== null;
    } catch {
        return false;
    }
}

function setMemoryContext(chatId: string, ctx: MemoryContext): void {
    if (!chatId) return;
    try {
        sessionStorage.setItem(memoryKey(chatId), JSON.stringify(ctx));
    } catch (err) {
        console.warn(`[Memory] Failed to write sessionStorage for chat "${chatId}":`, err);
    }
}

function sliceMessages(messages: BuddhiAIMessage[]): MessageSlice {
    if (messages.length === 0) {
        return { system: [], firstTurn: [], middle: [], lastTurn: [] };
    }

    // Separate system message
    let bodyStart = 0;
    const system: BuddhiAIMessage[] = [];
    if (messages[0].role === "system") {
        system.push(messages[0]);
        bodyStart = 1;
    }

    const body = messages.slice(bodyStart);

    // Need at least 6 body messages (3 full turns) for a non-empty middle.
    // With fewer messages there's nothing meaningful to summarize.
    if (body.length < 6) {
        // Still split correctly for consistency, even if middle is empty.
        const firstTurn = body.slice(0, Math.min(2, body.length));
        const remaining = body.slice(firstTurn.length);
        const lastTurn = remaining.length >= 2 ? remaining.slice(-2) : remaining;
        const middle = remaining.slice(0, remaining.length - lastTurn.length);
        return { system, firstTurn, middle, lastTurn };
    }

    const firstTurn = body.slice(0, 2);
    const lastTurn = body.slice(-2);
    // Cap the middle slice to avoid excessively large summarization prompts.
    const rawMiddle = body.slice(2, -2);
    const middle =
        rawMiddle.length > MAX_MIDDLE_MESSAGES
            ? rawMiddle.slice(-MAX_MIDDLE_MESSAGES)
            : rawMiddle;

    return { system, firstTurn, middle, lastTurn };
}

function applyMemoryContext(
    messages: BuddhiAIMessage[],
    chatId: string,
): BuddhiAIMessage[] {
    if (!chatId) return messages;

    const ctx = getMemoryContext(chatId);
    if (!ctx) return messages;

    const { middle } = sliceMessages(messages);
    if (middle.length === 0) {
        // Nothing was summarized yet — history is short enough to pass through.
        return messages;
    }

    const { system, firstTurn, lastTurn } = sliceMessages(messages);

    const summaryMessage: BuddhiAIMessage = {
        role: "assistant",
        content:
            `[Conversation summary — ${new Date(ctx.createdAt).toLocaleString()}]\n\n` +
            ctx.summary,
    };

    console.debug(
        `[Memory] Applied memory context for chat "${chatId}". ` +
        `Replaced ${middle.length} middle messages with summary.`
    );

    return [...system, ...firstTurn, summaryMessage, ...lastTurn];
}

async function runSummarization(
    instance: LlmInference,
    uiMessages: UIMessage[],
    systemPrompt: string,
    chatId: string,
    templateVersion: GemmaTemplateVersion,
): Promise<string> {
    if (!chatId) {
        throw new Error("[Memory] runSummarization called without a chatId.");
    }

    const messages = extractBuddhiMessages(uiMessages, systemPrompt, templateVersion);
    const { middle } = sliceMessages(messages);

    if (middle.length === 0) {
        console.debug(
            "[Memory] Skipping summarization — middle slice is empty " +
            `(conversation has ${messages.length} messages total).`
        );
        return "";
    }

    const conversationText = middle.map(formatMessageForSummary).join("\n\n");

    const summarizationMessages: BuddhiAIMessage[] = [
        {
            role: "system",
            content:
                "You are a summarization assistant. Your sole task is to create a " +
                "comprehensive yet concise summary of the conversation excerpt provided. " +
                "Include: key topics discussed, decisions made, code written or reviewed, " +
                "questions asked and answered, any important facts or context established, " +
                "and the overall progression of the conversation. " +
                "Write the summary in third-person prose. Do not add commentary or preamble — " +
                "output only the summary itself.",
        },
        {
            role: "user",
            content:
                "Please summarize the following conversation excerpt. " +
                "The summary will be used as working memory to continue the conversation:\n\n" +
                `<CONVERSATION>\n${conversationText}\n</CONVERSATION>`,
        },
    ];

    let prompt;
    try {
        prompt = await generateChatTemplate(summarizationMessages, { templateVersion });
    } catch (err) {
        const msg = err instanceof Error ? err.message : String(err);
        throw new Error(`[Memory] Failed to build summarization template: ${msg}`);
    }

    console.debug(
        `[Memory] Running summarization for chat "${chatId}" ` +
        `(${middle.length} messages in middle slice).`
    );

    const summary = await new Promise<string>((resolve, reject) => {
        let accumulated = "";
        try {
            instance.generateResponse(prompt, (chunk: string, done: boolean) => {
                if (done) {
                    // Strip trailing template tokens that may bleed through.
                    const clean = accumulated
                        .trim()
                        .replace(/<turn\|>\s*$/, "")
                        .replace(/<end_of_turn>\s*$/, "")
                        .trim();
                    resolve(clean);
                } else {
                    accumulated += chunk;
                }
            });
        } catch (err) {
            reject(
                new Error(
                    `[Memory] generateResponse threw during summarization: ${err instanceof Error ? err.message : String(err)
                    }`
                )
            );
        }
    });

    if (!summary) {
        throw new Error("[Memory] Summarization produced an empty result.");
    }

    const ctx: MemoryContext = {
        chatId,
        summary,
        summaryTokenCount: 0, // Counted separately if needed; kept as 0 to avoid extra LLM call.
        createdAt: Date.now(),
        originalMessageCount: messages.length,
    };
    setMemoryContext(chatId, ctx);

    console.debug(
        `[Memory] Summarization complete for chat "${chatId}". ` +
        `Summary length: ${summary.length} chars.`
    );

    return summary;
}

function getWorker(): Worker {
    if (typeof window === "undefined") {
        throw new Error("Model worker is only available in browser context.");
    }
    if (!_worker) {
        _worker = new Worker(
            new URL("../workers/model-download-worker.ts", import.meta.url),
            { type: "module" }
        );
        _worker.addEventListener("message", onWorkerMessage);
        _worker.addEventListener("error", onWorkerError);
    }
    return _worker;
}

function checkCacheForModel(modelId: string): Promise<boolean> {
    return new Promise((resolve) => {
        cacheCheckResolvers.set(modelId, resolve);
        getWorker().postMessage({ type: "check-cache", modelId } satisfies WorkerRequest);
    });
}

function modelCacheKey(modelId: string): string {
    return `https://cache.buddhi-ai.local/models/${modelId.replace(/\//g, "_")}`;
}

async function getModelObjectURL(modelId: string): Promise<string | null> {
    try {
        const cache = await caches.open(CACHE_NAME);
        const response = await cache.match(new Request(modelCacheKey(modelId)));
        if (!response) return null;
        const blob = await response.blob();
        return URL.createObjectURL(blob);
    } catch {
        return null;
    }
}

function onWorkerError(event: ErrorEvent): void {
    console.error("[model-manager] Worker error:", event.message, event.error);
}

function onWorkerMessage(event: MessageEvent<WorkerMessage>): void {
    const msg = event.data;
    const store = useModelStore.getState();

    switch (msg.type) {
        case "progress": {
            const { modelId, percentage } = msg as ProgressMessage;
            store.setModel(modelId, { status: "downloading", progress: percentage });
            break;
        }

        case "complete": {
            const { modelId } = msg as CompleteMessage;
            store.setModel(modelId, { status: "completed", progress: 100, error: undefined });
            break;
        }

        case "error": {
            const { modelId, message, code } = msg as ErrorMessage;
            if (code === "CANCELLED") {
                // User-initiated cancel — reset to not_installed instead of failed
                store.setModel(modelId, { status: "not_installed", progress: 0, error: undefined });
            } else {
                store.setModel(modelId, { status: "failed", progress: 0, error: message });
            }
            break;
        }

        case "cache-status": {
            const { modelId, cached } = msg as CacheStatusMessage;
            const resolver = cacheCheckResolvers.get(modelId);
            if (resolver) {
                resolver(cached);
                cacheCheckResolvers.delete(modelId);
            }
            break;
        }

        case "deleted": {
            const { modelId } = msg as DeletedMessage;
            store.removeModel(modelId);
            const resolver = deleteResolvers.get(modelId);
            if (resolver) {
                resolver();
                deleteResolvers.delete(modelId);
            }
            break;
        }
    }
}

function toModelInfo(id: string, state: ModelState, config: ModelConfig): ModelInfo {
    return {
        id,
        name: config.name,
        type: config.type,
        status: state.status,
        progress: state.progress,
        error: state.error,
    };
}

function slugify(fileName: string): string {
    const base = fileName.replace(/\.[^./]+$/, "");
    const slug = base
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "");
    return slug || "document";
}

function uniqueConceptId(base: string, existingIds?: Set<string>): string {
    if (!existingIds || !existingIds.has(base)) return base;

    let n = 2;
    while (existingIds.has(`${base}-${n}`)) n++;
    return `${base}-${n}`;
}

function toConceptId(fileName: string, existingIds?: Set<string>): string {
    return uniqueConceptId(slugify(fileName), existingIds);
}

function buildMessages(fileName: string, text: string): BuddhiAIMessage[] {
    const excerpt = text.slice(0, MAX_BODY_CHARS);
    return [
        {
            role: "system",
            content:
                "You decompose documents into a knowledge graph for a knowledge base. Given a " +
                "file name and its content, split it into between 3 and 8 distinct concepts — " +
                "topics, entities, sections, or ideas covered by the document. Respond with " +
                "STRICT JSON only — no markdown fences, no commentary, no text before or after. " +
                'Schema: {"concepts": [{"slug": string, "title": string, "type": string, ' +
                '"tags": string[], "description": string, "body": string, "relatesTo": string[]}]}. ' +
                '"slug" is a short unique kebab-case identifier for the concept within this ' +
                'response. "type" is a short 1-3 word noun phrase naming the kind of concept ' +
                '(e.g. "Topic", "Entity", "Procedure", "Definition"). "tags" is up to 6 short ' +
                'lowercase keywords. "description" is one concise sentence. "body" is a 1-2 sentence ' +
                'markdown summary of just that concept. "relatesTo" is a list ' +
                'of OTHER concepts\' "slug" values from this same response that this concept is ' +
                "directly related to — omit it or leave it empty if none. Output only the JSON object.",
        },
        {
            role: "user",
            content: `File name: ${fileName}\n\nContent:\n${excerpt}`,
        },
    ];
}

function repairTruncatedJson(raw: string): unknown | null {
    const stack: string[] = [];
    let inString = false;
    let escape = false;
    let lastSafeIndex = -1;
    let lastSafeStack: string[] = [];

    for (let i = 0; i < raw.length; i++) {
        const ch = raw[i];
        if (inString) {
            if (escape) escape = false;
            else if (ch === "\\") escape = true;
            else if (ch === '"') inString = false;
            continue;
        }
        if (ch === '"') {
            inString = true;
            continue;
        }
        if (ch === "{" || ch === "[") {
            stack.push(ch);
        } else if (ch === "}" || ch === "]") {
            stack.pop();
            if (ch === "}" && stack.length > 0 && stack[stack.length - 1] === "[") {
                lastSafeIndex = i + 1;
                lastSafeStack = [...stack];
            }
        }
    }

    if (lastSafeIndex === -1) return null;

    let truncated = raw.slice(0, lastSafeIndex);
    for (let i = lastSafeStack.length - 1; i >= 0; i--) {
        truncated += lastSafeStack[i] === "{" ? "}" : "]";
    }

    try {
        return JSON.parse(truncated);
    } catch {
        return null;
    }
}

function slugifyCandidate(raw: string): string {
    return raw
        .toLowerCase()
        .trim()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-+|-+$/g, "")
        .slice(0, MAX_SLUG_LENGTH);
}

function sanitize(parsed: unknown): DecomposedConcept[] | null {
    if (!parsed || typeof parsed !== "object") return null;
    
    // Accept either {"concepts": [...]} or bare [...]
    let list: unknown = (parsed as Record<string, unknown>).concepts;
    if (!Array.isArray(list)) {
        // Try as bare array if not wrapped
        if (Array.isArray(parsed)) {
            list = parsed;
        } else {
            console.warn("[okf/decompose] Missing or invalid 'concepts' field; got:", typeof parsed === "object" ? Object.keys(parsed) : typeof parsed);
            return null;
        }
    }

    if (!Array.isArray(list)) return null;

    const usedSlugs = new Set<string>();
    const rawEntries: { slug: string; entry: Record<string, unknown> }[] = [];

    for (const item of list) {
        if (!item || typeof item !== "object") continue;
        const obj = item as Record<string, unknown>;

        if (typeof obj.title !== "string" || !obj.title.trim()) continue;
        if (typeof obj.body !== "string" || !obj.body.trim()) continue;

        let slug = typeof obj.slug === "string" ? slugifyCandidate(obj.slug) : "";
        if (!slug) slug = slugifyCandidate(obj.title);
        if (!slug) continue;

        if (usedSlugs.has(slug)) {
            let n = 2;
            while (usedSlugs.has(`${slug}-${n}`)) n++;
            slug = `${slug}-${n}`;
        }
        usedSlugs.add(slug);

        rawEntries.push({ slug, entry: obj });
        if (rawEntries.length >= MAX_CONCEPTS) break;
    }

    if (rawEntries.length < MIN_CONCEPTS) {
        console.warn(`[okf/decompose] Too few concepts: found ${rawEntries.length}, need ≥${MIN_CONCEPTS}`);
        return null;
    }

    const result: DecomposedConcept[] = rawEntries.map(({ slug, entry }) => {
        const tags = Array.isArray(entry.tags)
            ? [
                  ...new Set(
                      entry.tags
                          .filter((t): t is string => typeof t === "string" && t.trim().length > 0)
                          .map((t) => t.trim().slice(0, MAX_TAG_LENGTH))
                  ),
              ].slice(0, MAX_TAGS)
            : [];

        const relatesTo = Array.isArray(entry.relatesTo)
            ? [
                  ...new Set(
                      entry.relatesTo
                          .filter((r): r is string => typeof r === "string")
                          .map((r) => slugifyCandidate(r))
                          .filter((r) => r && r !== slug && usedSlugs.has(r))
                  ),
              ]
            : [];

        return {
            slug,
            title: String(entry.title).trim().slice(0, MAX_TITLE_LENGTH),
            type:
                typeof entry.type === "string" && entry.type.trim()
                    ? entry.type.trim().slice(0, MAX_TYPE_LENGTH)
                    : "Concept",
            tags,
            description:
                typeof entry.description === "string"
                    ? entry.description.trim().slice(0, MAX_DESCRIPTION_LENGTH)
                    : "",
            body: String(entry.body).trim(),
            relatesTo,
        };
    });

    return result;
}

function stripCodeFences(raw: string): string {
    const trimmed = raw.trim();
    const fenced = trimmed.match(/^```(?:json)?\s*([\s\S]*?)\s*```$/i);
    return fenced ? fenced[1].trim() : trimmed;
}

async function runDecomposition(
    instance: LlmInference,
    fileName: string,
    text: string
): Promise<DecomposedConcept[] | null> {
    const prompt = await generateChatTemplate(buildMessages(fileName, text));

    const raw = await new Promise<string>((resolve, reject) => {
        let accumulated = "";
        try {
            instance.generateResponse(prompt, (chunk: string, done: boolean) => {
                if (done) {
                    resolve(accumulated.trim().replace(/<turn\|>\s*$/, "").replace(/<end_of_turn>\s*$/, "").trim());
                } else {
                    accumulated += chunk;
                }
            });
        } catch (err) {
            reject(err);
        }
    });

    console.debug("[okf/decompose] Model response:", raw.slice(0, 500));
    const cleaned = stripCodeFences(raw);

    let parsed: unknown;
    try {
        parsed = JSON.parse(cleaned);
    } catch (err) {
        const repaired = repairTruncatedJson(cleaned);
        if (repaired === null) throw err;
        console.warn("[okf/decompose] Response was truncated; recovered partial concepts from what parsed cleanly.");
        parsed = repaired;
    }

    return sanitize(parsed);
}

function extractConceptsWithLlm(
    instance: LlmInference,
    fileName: string,
    text: string
): Promise<DecomposedConcept[] | null> {
    return enqueueLlmCall(async () => {
        try {
            return await runDecomposition(instance, fileName, text);
        } catch (err) {
            console.warn("[okf/decompose] LLM decomposition failed, falling back to single concept:", err);
            return null;
        }
    });
}

function buildMessages(fileName: string, body: string): BuddhiAIMessage[] {
