function parseFrontmatter(raw: string): {
    frontmatter: OkfFrontmatter;
    body: string;
} {
    const { data, content } = matter(raw);
    return {
        frontmatter: data as OkfFrontmatter,
        body: content.trim(),
    };
}

function serializeFrontmatter(frontmatter: OkfFrontmatter, body: string): string {
    return matter.stringify(body, frontmatter);
}

function normalizeSegments(parts: string[]): string[] {
	const out: string[] = [];
	for (const part of parts) {
		if (part === "" || part === ".") continue;
		if (part === "..") {
			out.pop();
			continue;
		}
		out.push(part);
	}
	return out;
}

function resolveConceptLink(fromId: string, href: string): string | null {
	const path = href.split(/[?#]/)[0];
	if (!path) return null;
	if (/^[a-z][a-z0-9+.-]*:/i.test(path)) return null; // http:, mailto:, data:, etc.

	let stripped = path;
	if (stripped.toLowerCase().endsWith(".md")) {
		stripped = stripped.slice(0, -3);
	} else if (stripped.toLowerCase().endsWith(".markdown")) {
		stripped = stripped.slice(0, -9);
	}

	if (stripped.startsWith("/")) {
		const resolved = normalizeSegments(stripped.split("/")).join("/");
		return resolved || null;
	}

	// Path-relative: resolve against the directory containing `fromId`.
	const fromParts = fromId.split("/");
	fromParts.pop();
	const resolved = normalizeSegments([...fromParts, ...stripped.split("/")]).join("/");
	return resolved || null;
}

function extractLinkTargetsWithKind(concept: OkfConcept): LinkWithKind[] {
	const result: LinkWithKind[] = [];
	const seenTargets = new Set<string>();

	// Find the position of the "# Concepts" heading to detect root→sub links (tolerant to CRLF / # levels)
	const conceptsHeadingMatch = concept.body.match(/(?:^|\r?\n)#+\s*Concepts\b/i);
	const conceptsHeadingIdx = conceptsHeadingMatch ? (conceptsHeadingMatch.index ?? -1) : -1;

	for (const match of concept.body.matchAll(LINK_RE)) {
		if (match[1] === "!") continue; // skip image embeds
		const target = resolveConceptLink(concept.id, match[2]);
		if (!target || target === concept.id || seenTargets.has(target)) continue;
		seenTargets.add(target);

		let kind: "containment" | "relatesTo" | "reference" = "reference";

		// Check if preceded by "Part of "
		const beforeMatch = concept.body.slice(Math.max(0, (match.index ?? 0) - 60), match.index ?? 0);
		if (/Part\s+of\s*$/i.test(beforeMatch) || beforeMatch.includes("Part of ")) {
			kind = "containment";
		}
		// Check if inside "See also:" line
		else if (beforeMatch.includes("See also:")) {
			kind = "relatesTo";
		}
		// Check if after "# Concepts" heading
		else if (conceptsHeadingIdx !== -1 && (match.index ?? 0) > conceptsHeadingIdx) {
			kind = "containment";
		}

		result.push({ target, kind });
	}

	return result;
}

function buildConceptGraph(concepts: OkfConcept[]): ConceptGraph {
	const existingIds = new Set(concepts.map((c) => c.id));
	const nodes = new Map<string, GraphNodeData>();
	const edges: { data: GraphEdgeData }[] = [];
	const backlinks = new Map<string, string[]>();
	const seenEdgeKeys = new Set<string>();

	for (const c of concepts) {
		nodes.set(c.id, {
			id: c.id,
			label: c.frontmatter.title || c.id,
			type: c.frontmatter.type || "Document",
			tags: c.frontmatter.tags ?? [],
			placeholder: false,
		});
	}

	for (const c of concepts) {
		for (const link of extractLinkTargetsWithKind(c)) {
			const key = `${c.id}->${link.target}`;
			if (seenEdgeKeys.has(key)) continue;
			seenEdgeKeys.add(key);
			edges.push({ data: { id: key, source: c.id, target: link.target, kind: link.kind } });

			if (!existingIds.has(link.target) && !nodes.has(link.target)) {
				nodes.set(link.target, {
					id: link.target,
					label: link.target,
					type: "(unresolved)",
					tags: [],
					placeholder: true,
				});
			}

			const list = backlinks.get(link.target);
			if (list) list.push(c.id);
			else backlinks.set(link.target, [c.id]);
		}
	}

	return {
		nodes: [...nodes.values()].map((data) => ({ data })),
		edges,
		backlinks,
	};
}

function extractLinkTargets(concept: OkfConcept): string[] {
	return extractLinkTargetsWithKind(concept).map(link => link.target);
}

async function extractText(file: File): Promise<string> {
    const ext = file.name.split(".").pop()?.toLowerCase();

    let text: string;
    if (ext === "pdf") {
        text = await extractTextFromPDF(file);
    } else {
        text = await file.text();
    }

    if (!text || text.trim().length === 0) {
        throw new Error(
            ext === "pdf"
                ? "No extractable text found. Scanned/image-only PDFs are not supported — please use a text-based PDF."
                : "File appears to be empty."
        );
    }

    return text;
}

function humanizeTitle(fileName: string): string {
    return fileName
        .replace(/\.[^./]+$/, "")
        .replace(/[-_]+/g, " ")
        .trim();
}

function fileToConcept(
    file: File,
    text: string,
    existingIds?: Set<string>
): FileToConceptResult {
    const id = toConceptId(file.name, existingIds);
    const ext = file.name.split(".").pop()?.toLowerCase();
    const trimmed = text.trim();

    let frontmatter: OkfFrontmatter | null = null;
    let body = trimmed;

    if (ext === "md" && /^---\s*\r?\n/.test(trimmed)) {
        try {
            const parsed = parseFrontmatter(trimmed);
            if (typeof parsed.frontmatter.type === "string" && parsed.frontmatter.type.trim()) {
                frontmatter = parsed.frontmatter;
                body = parsed.body;
            }
        } catch {
            // Malformed YAML frontmatter — fall through to synthesized frontmatter.
        }
    }

    const enrichable = frontmatter === null;
    if (!frontmatter) {
        frontmatter = {
            type: "Document",
            title: humanizeTitle(file.name),
            generated: { by: PRODUCER_ACTOR, at: new Date().toISOString() },
        };
    }

    const raw = serializeFrontmatter(frontmatter, body);

    return {
        concept: {
            id,
            frontmatter,
            body,
            raw,
            fileName: file.name,
            fileSize: file.size,
            createdAt: new Date().toISOString(),
        },
        enrichable,
    };
}

async function extractTextFromPDF(file: File): Promise<string> {
    try {
        // Load pdfjs-dist directly from CDN, bypassing Webpack bundling.
        // pdfjs-dist v5 ESM uses Object.defineProperty patterns that break
        // when bundled by Webpack — the webpackIgnore comment skips bundling.
        // @ts-expect-error — TypeScript doesn't resolve URL imports; the browser handles this at runtime
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const pdfjsLib: any = await import(/* webpackIgnore: true */ "https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.449/build/pdf.min.mjs");

        // Fetch the worker bundle and serve it as a same-origin blob.
        // Using an `import` proxy statement fails for classic workers (SyntaxError),
        // causing getTextContent() to silently return empty items.
        // Fetching the full bundle content works for both classic and module workers.
        const workerResponse = await fetch(
            "https://cdn.jsdelivr.net/npm/pdfjs-dist@5.4.449/build/pdf.worker.min.mjs"
        );
        const workerText = await workerResponse.text();
        const workerBlob = new Blob([workerText], { type: "text/javascript" });
        const workerBlobUrl = URL.createObjectURL(workerBlob);
        pdfjsLib.GlobalWorkerOptions.workerSrc = workerBlobUrl;

        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

        let fullText = "";

        for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
            const page = await pdf.getPage(pageNum);
            const textContent = await page.getTextContent();
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            const pageText = textContent.items.map((item: any) => item.str).join(" ");
            fullText += pageText + "\n";
            // Yield to the event loop after each page so the UI stays responsive
            // during extraction of large, multi-page PDFs.
            await new Promise((r) => setTimeout(r, 0));
        }

        URL.revokeObjectURL(workerBlobUrl);
        return fullText.trim();
    } catch (error) {
        console.error("Error extracting text from PDF:", error);
        throw new Error(
            `Failed to extract text from PDF: ${error instanceof Error ? error.message : "Unknown error"
            }`
        );
    }
}

function createIndex(): MiniSearch<IndexedDoc> {
    return new MiniSearch<IndexedDoc>({
        idField: "id",
        fields: ["title", "tags", "body"],
        storeFields: [],
        searchOptions: {
            boost: { title: 2, tags: 1.5 },
            fuzzy: 0.2,
            prefix: true,
        },
    });
}

async function ensureHydrated(): Promise<MiniSearch<IndexedDoc>> {
    if (index) return index;
    if (!hydratePromise) {
        hydratePromise = (async () => {
            const concepts = await getAllConcepts();
            const built = createIndex();
            built.addAll(concepts.map(toIndexedDoc));
            index = built;
        })();
    }
    await hydratePromise;
    return index!;
}

async function removeFromIndex(id: string): Promise<void> {
    const idx = await ensureHydrated();
    if (idx.has(id)) idx.discard(id);
}

async function search(query: string, topK: number): Promise<OkfSearchHit[]> {
    const idx = await ensureHydrated();
    return idx
        .search(query)
        .slice(0, topK)
        .map((r) => ({ id: r.id as string, score: r.score }));
}

function toIndexedDoc(concept: OkfConcept): IndexedDoc {
    return {
        id: concept.id,
        title: concept.frontmatter.title ?? concept.fileName,
        tags: (concept.frontmatter.tags ?? []).join(" "),
        body: concept.body,
    };
}

async function indexConcept(concept: OkfConcept): Promise<void> {
    const idx = await ensureHydrated();
    const doc = toIndexedDoc(concept);
    if (idx.has(concept.id)) idx.replace(doc);
    else idx.add(doc);
}

function openDB(): Promise<IDBDatabase> {
    if (_db) return Promise.resolve(_db);

    return new Promise((resolve, reject) => {
        const req = indexedDB.open(DB_NAME, DB_VERSION);

        req.onerror = () =>
            reject(new Error(`Failed to open OKF store: ${req.error?.message ?? req.error}`));

        req.onsuccess = () => {
            _db = req.result;
            req.result.onclose = () => { _db = null; };
            resolve(req.result);
        };

        req.onupgradeneeded = () => {
            const db = req.result;
            if (!db.objectStoreNames.contains(STORE_NAME)) {
                db.createObjectStore(STORE_NAME, { keyPath: "id" });
            }
        };
    });
}

async function deleteConcept(id: string): Promise<void> {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, "readwrite");
        const req = tx.objectStore(STORE_NAME).delete(id);
        req.onsuccess = () => resolve();
        req.onerror = () =>
            reject(new Error(`OKF store delete failed: ${req.error?.message ?? req.error}`));
    });
}

async function getAllConcepts(): Promise<OkfConcept[]> {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, "readonly");
        const req = tx.objectStore(STORE_NAME).getAll();
        req.onsuccess = () => resolve(req.result ?? []);
        req.onerror = () =>
            reject(new Error(`OKF store getAll failed: ${req.error?.message ?? req.error}`));
    });
}

async function getConcept(id: string): Promise<OkfConcept | null> {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, "readonly");
        const req = tx.objectStore(STORE_NAME).get(id);
        req.onsuccess = () => resolve(req.result ?? null);
        req.onerror = () =>
            reject(new Error(`OKF store get failed: ${req.error?.message ?? req.error}`));
    });
}

async function hasConcepts(): Promise<boolean> {
    try {
        const db = await openDB();
        return new Promise((resolve, reject) => {
            const tx = db.transaction(STORE_NAME, "readonly");
            const req = tx.objectStore(STORE_NAME).count();
            req.onsuccess = () => resolve(req.result > 0);
            req.onerror = () =>
                reject(new Error(`OKF store count failed: ${req.error?.message ?? req.error}`));
        });
    } catch {
        return false;
    }
}

async function putConcept(concept: OkfConcept): Promise<void> {
    const db = await openDB();
    return new Promise((resolve, reject) => {
        const tx = db.transaction(STORE_NAME, "readwrite");
        const req = tx.objectStore(STORE_NAME).put(concept);
        req.onsuccess = () => resolve();
        req.onerror = () =>
            reject(new Error(`OKF store put failed: ${req.error?.message ?? req.error}`));
    });
}

function buildRagContextBlock(segments: RagSegment[]): string | null {
    if (segments.length === 0) return null;

    const sourceBlocks = segments
        .map(
            (seg, i) =>
                `[Source ${i + 1}: "${seg.fileName}"]\n${seg.text.trim()}`
        )
        .join("\n\n");

    return (
        "\n\n---\n" +
        "Relevant context from your knowledge base:\n\n" +
        sourceBlocks +
        "\n\n" +
        "Use the above context to help answer the question. " +
        "If the context is not relevant, ignore it and answer from your general knowledge."
    );
}

async function retrieveRagContext(
    query: string,
    topK: number = DEFAULT_TOP_K,
    minScoreRatio: number = DEFAULT_MIN_SCORE_RATIO
): Promise<RagSegment[]> {
    // Guard: nothing to retrieve for a blank query.
    if (!query.trim()) return [];

    console.log(`[rag] retrieveRagContext — query: "${query.slice(0, 80)}${query.length > 80 ? "…" : ""}"`);

    try {
        // Early exit when no documents are indexed.
        const hasAny = await hasConcepts();
        console.log(`[rag] hasConcepts: ${hasAny}`);
        if (!hasAny) return [];

        const hits = await search(query, topK);
        console.log(`[rag] raw hits (${hits.length}):`, hits);

        if (hits.length === 0) return [];

        // ── Filter by score relative to the top hit ───────────────────────
        const topScore = hits[0].score;
        const filtered = hits.filter((h) => h.score >= topScore * minScoreRatio);
        console.log(`[rag] after ratio filter (>= ${minScoreRatio} of top): ${filtered.length} results`);

        // ── Fetch concept bodies and project to RagSegment[] ──────────────
        const segments: RagSegment[] = [];
        for (const hit of filtered) {
            const concept = await getConcept(hit.id);
            if (!concept) continue;
            segments.push({
                text: concept.body.slice(0, MAX_SOURCE_CHARS),
                fileName: concept.frontmatter.title ?? concept.fileName,
                documentId: concept.id,
                score: hit.score,
            });
        }

        console.log(`[rag] final segments (${segments.length}):`, segments.map((s) => ({
            fileName: s.fileName,
            score: s.score,
        })));
        return segments;
    } catch (err) {
        console.warn(
            "[rag] Retrieval failed — continuing without RAG context.",
            err instanceof Error
                ? `${err.name}: ${err.message}`
                : String(err)
        );
        return [];
    }
}

function toSourceItems(segments: RagSegment[]): RagSourceItem[] {
    return segments.map((s) => ({
        fileName: s.fileName,
        documentId: s.documentId,
    }));
}

