async delete(id: string): Promise<void> {
        try {
            const idb = await getDB();
            await deleteItemFromStore(idb, "chats", id);
        } catch (error) {
            console.error("[chatsApi.delete] error:", error);
            throw error;
        }
    }

async list(
        limit: number = 10,
        offset: number = 0
    ): Promise<{ chats: ChatInfo[]; total: number }> {
        try {
            const idb = await getDB();
            const all = await getAllFromStore<BuddhiAISavedChat>(idb, "chats");

            const sorted = [...all].sort((a, b) => {
                const aTime = a.updated_at
                    ? new Date(a.updated_at).getTime()
                    : parseInt(a.id, 10) || 0;
                const bTime = b.updated_at
                    ? new Date(b.updated_at).getTime()
                    : parseInt(b.id, 10) || 0;
                return bTime - aTime;
            });

            return {
                chats: sorted.slice(offset, offset + limit).map(toChatInfo),
                total: sorted.length,
            };
        } catch (error) {
            console.error("[chatsApi.list] error:", error);
            throw error;
        }
    }

async deleteDocument(id: number): Promise<void> {
        const record = await idbGet(id);

        const conceptIds = record?.concept_ids ?? (record?.concept_id ? [record.concept_id] : []);

        for (const conceptId of conceptIds) {
            try {
                await deleteConcept(conceptId);
                await removeFromIndex(conceptId);
            } catch (err) {
                console.error(
                    `[documents] Failed to delete OKF concept "${conceptId}" for doc ${id} — continuing with IDB deletion:`,
                    err
                );
            }
        }

        await idbDelete(id);
        useDocumentStore.getState().removeDoc(id);
    }

async getDocument(id: number): Promise<DocumentInfo> {
        const record = await idbGet(id);
        if (!record) throw new Error(`Document ${id} not found.`);
        return toInfo(record);
    }

async listDocuments(): Promise<DocumentInfo[]> {
        try {
            const records = await idbGetAll();
            return records
                .map(toInfo)
                .sort(
                    (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime()
                );
        } catch (err) {
            throw new Error(
                `Failed to load documents: ${err instanceof Error ? err.message : String(err)}`
            );
        }
    }

async uploadDocument(file: File): Promise<DocumentInfo> {
        // ── Validate extension ────────────────────────────────────────────────
        const ext = file.name.split(".").pop()?.toLowerCase() ?? "";
        if (!SUPPORTED_EXTENSIONS.includes(ext)) {
            throw new Error(
                `Unsupported file type ".${ext}". Please upload a PDF, TXT, or MD file.`
            );
        }

        // ── Validate size ─────────────────────────────────────────────────────
        if (file.size > MAX_FILE_SIZE_BYTES) {
            throw new Error(
                `"${file.name}" is ${(file.size / 1024 / 1024).toFixed(1)} MB — ` +
                `files must be 25 MB or smaller.`
            );
        }

        // ── Capacity check ────────────────────────────────────────────────────
        const activeCount = useDocumentStore.getState().activeCount;
        if (activeCount >= 5) {
            throw new Error(
                "Processing queue is full (5/5 slots in use). Wait for a document to finish before uploading more."
            );
        }

        // ── Read bytes ────────────────────────────────────────────────────────
        let fileData: ArrayBuffer;
        try {
            fileData = await file.arrayBuffer();
        } catch {
            throw new Error(`Could not read "${file.name}". The file may be locked or corrupted.`);
        }

        // ── Build record ──────────────────────────────────────────────────────
        const id = Date.now();
        const doc: DocumentInfo = {
            id,
            original_name: file.name,
            file_size: file.size,
            status: "pending",
            concept_id: null,
            concept_ids: null,
            error_msg: null,
            created_at: new Date().toISOString(),
        };

        // ── Persist to IDB ────────────────────────────────────────────────────
        try {
            await idbPut({ ...doc, file_data: fileData });
        } catch (err) {
            const msg = err instanceof Error ? err.message : String(err);
            if (msg.toLowerCase().includes("quota")) {
                throw new Error(
                    "Browser storage quota exceeded. Delete some documents to free space before uploading."
                );
            }
            throw new Error(`Failed to save document to local storage: ${msg}`);
        }

        // ── Register in Zustand & kick off pipeline ───────────────────────────
        useDocumentStore.getState().initDoc(id);
        runPipeline(doc, fileData); // intentionally not awaited

        return doc;
    }

async cancelDownload(modelId: string): Promise<void> {
        const config = MODELS.find((m) => m.id === modelId);
        if (!config) throw new Error(`Model "${modelId}" not found in configuration.`);

        getWorker().postMessage({ type: "cancel", modelId } satisfies WorkerRequest);
    }

async deleteModel(id: string): Promise<void> {
        const config = MODELS.find((m) => m.id === id);
        if (!config) throw new Error(`Model "${id}" not found in configuration.`);

        return new Promise<void>((resolve, reject) => {
            deleteResolvers.set(id, resolve);

            // Timeout guard — if worker doesn't respond in 10 s, fall back to store removal
            const timer = setTimeout(() => {
                deleteResolvers.delete(id);
                useModelStore.getState().removeModel(id);
                reject(new Error("Delete operation timed out; model removed from store anyway."));
            }, 10_000);

            // Wrap resolver so we also clear the timer
            const originalResolve = deleteResolvers.get(id)!;
            deleteResolvers.set(id, () => {
                clearTimeout(timer);
                originalResolve();
            });

            getWorker().postMessage({ type: "delete", modelId: id } satisfies WorkerRequest);
        });
    }

async downloadModel(data: ModelDownloadRequest): Promise<ModelInfo> {
        const { model: modelId } = data;
        const config = MODELS.find((m) => m.id === modelId);

        if (!config) {
            throw new Error(`Model "${modelId}" not found in configuration.`);
        }

        const store = useModelStore.getState();
        const current = store.models[modelId];

        if (current?.status === "downloading") {
            throw new Error(`Model "${config.name}" is already downloading.`);
        }

        // Optimistically set store before worker confirms
        store.setModel(modelId, { status: "downloading", progress: 0, error: undefined });

        try {
            getWorker().postMessage({
                type: "download",
                modelId,
                repoId: config.id,
                filename: config.modelFile,
                accessToken: data.accessToken,
            } satisfies WorkerRequest);
        } catch (err) {
            // Worker creation failed (e.g., unsupported browser)
            store.setModel(modelId, {
                status: "failed",
                progress: 0,
                error: `Failed to start download worker: ${(err as Error).message}`,
            });
            throw err;
        }

        const state = store.models[modelId]!;
        return toModelInfo(modelId, state, config);
    }

getModelStatus(id: string): ModelInfo {
        const config = MODELS.find((m) => m.id === id);
        if (!config) throw new Error(`Model "${id}" not found in configuration.`);

        const store = useModelStore.getState();
        const state = store.models[id] ?? { status: "not_installed", progress: 0 };
        return toModelInfo(id, state, config);
    }

async listModels(): Promise<ModelInfo[]> {
        const store = useModelStore.getState();
        const result: ModelInfo[] = [];

        // Kick off all cache checks in parallel
        const cacheChecks = await Promise.all(
            MODELS.map((config) => checkCacheForModel(config.id).catch(() => false))
        );

        MODELS.forEach((config, i) => {
            const cachedOnDisk = cacheChecks[i];
            const storeState = store.models[config.id];
            let finalState: ModelState;

            if (!storeState) {
                // No store entry — derive from cache
                finalState = cachedOnDisk
                    ? { status: "completed", progress: 100 }
                    : { status: "not_installed", progress: 0 };
                store.setModel(config.id, finalState);
            } else if (storeState.status === "downloading") {
                // Worker was killed (page reload) — no active download can exist for this model
                // since the worker is freshly created. Mark as interrupted.
                finalState = {
                    status: "failed",
                    progress: 0,
                    error: "Download was interrupted (page reloaded). Click Retry to restart.",
                };
                store.setModel(config.id, finalState);
            } else if (storeState.status === "completed" && !cachedOnDisk) {
                // Store says complete but cache is empty (e.g., browser cleared cache)
                finalState = { status: "not_installed", progress: 0 };
                store.setModel(config.id, finalState);
            } else if (storeState.status === "not_installed" && cachedOnDisk) {
                // Downloaded in another tab or manually
                finalState = { status: "completed", progress: 100 };
                store.setModel(config.id, finalState);
            } else {
                finalState = storeState;
            }

            result.push(toModelInfo(config.id, finalState, config));
        });

        return result;
    }

completeDoc(id) {
        set((s) => ({
            docs: {
                ...s.docs,
                [id]: {
                    ...s.docs[id],
                    status: "completed",
                    phase: null,
                    overallPct: 100,
                    errorMsg: null,
                },
            },
            activeCount: Math.max(0, s.activeCount - 1),
        }));
    }

failDoc(id, errorMsg) {
        set((s) => ({
            docs: {
                ...s.docs,
                [id]: {
                    ...s.docs[id],
                    status: "failed",
                    phase: null,
                    errorMsg,
                },
            },
            activeCount: Math.max(0, s.activeCount - 1),
        }));
    }

initDoc(id) {
        set((s) => ({
            docs: {
                ...s.docs,
                [id]: {
                    status: "pending",
                    phase: null,
                    overallPct: 0,
                    errorMsg: null,
                },
            },
            activeCount: s.activeCount + 1,
        }));
    }

removeDoc(id) {
        set((s) => {
            const { [id]: removed, ...rest } = s.docs;
            const wasActive =
                removed?.status === "pending" || removed?.status === "processing";
            return {
                docs: rest,
                activeCount: wasActive
                    ? Math.max(0, s.activeCount - 1)
                    : s.activeCount,
            };
        });
    }

updateProgress(id, phase, overallPct) {
        set((s) => ({
            docs: {
                ...s.docs,
                [id]: {
                    ...s.docs[id],
                    status: "processing",
                    phase,
                    overallPct,
                },
            },
        }));
    }
